    # Early rounds are more forgiving (half rate).
    base_rate = 0.3
    if round_num < 10:
        base_rate *= 0.5

    if observation['action'] == 'cooperate':
        # Move reputation upward with diminishing returns
        delta = base_rate * (1.0 - current_reputation)
    else:
        # Move reputation downward symmetrically
        delta = -base_rate * (current_reputation + 1.0)

    new_reputation = current_reputation + delta
    return max(-1.0, min(1.0, new_reputation))

def decide(recipient_reputation, round_num, my_history):
    # Dynamic threshold that starts moderate and gradually decreases.
    threshold = 0.5 - 0.004 * round_num

    # Personal history condition: if we have defected more than half the time,
    # become more cautious (higher threshold) to avoid exploitation.
    if my_history:
        coop_count = sum(1 for a in my_history if a == 'cooperate')
        if coop_count / len(my_history) < 0.5:
            threshold = min(threshold + 0.1, 1.0)

    return recipient_reputation > threshold
